        (inertial_b == NULL) || (mismatch_rad == NULL)) {
        if (mismatch_rad != NULL)
            *mismatch_rad = INFINITY;
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(body_a)) || (!adcs_is_finite_vec3(body_b)) ||
        (!adcs_is_finite_vec3(inertial_a)) || (!adcs_is_finite_vec3(inertial_b))) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    na = adcs_vec3_norm(body_a);
    if ((!isfinite(na)) || (na <= ADCS_EPS_NORM)) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    ua = adcs_vec3_scale(body_a, 1.0 / na);

    nb = adcs_vec3_norm(body_b);
    if ((!isfinite(nb)) || (nb <= ADCS_EPS_NORM)) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    ub = adcs_vec3_scale(body_b, 1.0 / nb);

    ni_a = adcs_vec3_norm(inertial_a);
    if ((!isfinite(ni_a)) || (ni_a <= ADCS_EPS_NORM)) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    ia = adcs_vec3_scale(inertial_a, 1.0 / ni_a);

    ni_b = adcs_vec3_norm(inertial_b);
    if ((!isfinite(ni_b)) || (ni_b <= ADCS_EPS_NORM)) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    ib = adcs_vec3_scale(inertial_b, 1.0 / ni_b);

    ca = ADCS_CLAMP(adcs_vec3_dot(&ua, &ub), -1.0, 1.0);
    ci = ADCS_CLAMP(adcs_vec3_dot(&ia, &ib), -1.0, 1.0);

    aa = acos(ca);
    ai = acos(ci);

    mismatch = fabs(aa - ai);

    if ((!isfinite(mismatch)) || (mismatch < 0.0) || (mismatch > ADCS_PI)) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    *mismatch_rad = mismatch;
    return ADCS_OK;
}

